mapper.update:
UPDATE proj_project_plan_version
SET status='EFFECTIVE', execution_snapshot=#{query.executionSnapshot}, effective_at=#{query.effectiveAt},
    version=version+1, updater=#{query.updater}, update_time=CURRENT_TIMESTAMP(3)
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND id=#{query.draftId}
  AND status='DRAFT' AND base_plan_version_id=#{query.oldPlanVersionId}
  AND version=#{query.expectedDraftVersion} AND deleted=0

UPDATE proj_project_plan_version SET status='SUPERSEDED', updater=#{query.updater}, update_time=CURRENT_TIMESTAMP(3)
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND id=#{query.oldPlanVersionId}
  AND status='EFFECTIVE' AND closed_at IS NULL AND deleted=0

UPDATE proj_project SET active_plan_version_id=#{query.draftId}, version=version+1,
    updater=#{query.updater}, update_time=CURRENT_TIMESTAMP(3)
WHERE tenant_id=#{query.tenantId} AND id=#{query.projectId}
  AND active_plan_version_id=#{query.oldPlanVersionId} AND version=#{query.expectedProjectVersion}
  AND lifecycle_status='ACTIVE' AND deleted=0

UPDATE proj_project SET active_plan_version_id=#{query.planVersionId}
WHERE tenant_id=#{query.tenantId} AND id=#{query.projectId} AND active_plan_version_id IS NULL
  AND lifecycle_status='ACTIVE' AND deleted=b'0'

UPDATE proj_project_plan_version SET closed_at=#{query.closedAt}, closure_result=#{query.evidence}
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND id=#{query.planVersionId}
  AND status='EFFECTIVE' AND closed_at IS NULL AND deleted=b'0'
